# Week 3 explicitly follows the active loops-to-campaign bridge.
LESSONS.update({
    (3, 1): {"title": "Loops and Bounded `range()` Practice", "intro": "Loops repeat a block of code so a program can process each record or attempt without duplicating statements. This lesson finishes the existing `for` and `while` mental model, then focuses on `range()` boundaries because off-by-one errors can skip a campaign record or retry too many times.", "concepts": [("`range()`", "`range(stop)`, `range(start, stop)`, and `range(start, stop, step)` produce bounded integer sequences with an exclusive stop."), ("Loop state", "A `while` loop needs state that changes toward a stopping condition."), ("Termination", "A loop terminates when its condition becomes false or a bounded iterable is exhausted."), ("Loop choice", "Use `for` for a known iterable or bounded count; use `while` when changing state controls continuation.")], "syntax": "`range(stop)`\n`range(start, stop)`\n`range(start, stop, step)`\n\n`while condition:\n    update_state()`", "examples": [ex('for attempt in range(1, 4):\n    print(f"Attempt {attempt}")', 'Attempt 1\nAttempt 2\nAttempt 3', "The stop value 4 is excluded."), ex('for value in range(2, 11, 3):\n    print(value)', '2\n5\n8', "The step is added while the next value remains below 11."), ex('attempt = 1\nwhile attempt <= 3:\n    print(attempt)\n    attempt += 1', '1\n2\n3', "The state update makes the condition eventually false.")], "domain": ex('max_attempts = 3\nfor attempt in range(1, max_attempts + 1):\n    print(f"Retry {attempt} of {max_attempts}")', 'Retry 1 of 3\nRetry 2 of 3\nRetry 3 of 3', "`max_attempts + 1` makes the inclusive human count fit an exclusive stop."), "mistakes": ["Using `range(1, max_attempts)` and silently skipping the last attempt.", "Forgetting the `while` state update and creating an infinite loop.", "Assuming `range(3, 1)` counts down without a negative step."], "questions": ["How many values are in `range(1, 4)`?", "What does `range(3, 1)` produce?", "What changes after each while-loop iteration?"], "quiz": [("Why is the stop 4 for three attempts?", ["Stop is exclusive", "Python adds one automatically", "It is random"], "a"), ("What prevents a while loop from running forever?", ["A changing state and reachable condition", "A print statement", "A dictionary"], "a")], "exercise": "Write `bounded_attempts(max_attempts)` using `range()` and `safe_countdown(start)` using `while`. Test zero, one, and three boundaries and assert that both loops terminate with the expected values.", "solution": 'def bounded_attempts(max_attempts):\n    return list(range(1, max_attempts + 1))\n\ndef safe_countdown(start):\n    values = []\n    current = start\n    while current > 0:\n        values.append(current)\n        current -= 1\n    return values', "test": "assert bounded_attempts(3) == [1, 2, 3]; assert safe_countdown(0) == []"},
    (3, 2): {"title": "Lists, Sets, `for`, `range()`, and `while`", "intro": "A campaign report usually contains many records. Lists preserve record order, dictionaries describe one record, and sets answer uniqueness or membership questions. You learned loops separately; now you combine them to transform a small collection without losing evidence or duplicating logic.", "concepts": [("List of records", "A list holds many records in processing order."), ("Set of unique values", "A set removes duplicates and supports membership checks."), ("Dictionary fields", "A dictionary gives each record named fields."), ("Looping choices", "Use `for` to process each record; use `while` only when state, not items, controls continuation.")], "syntax": "`records = [{\"name\": ..., \"status\": ...}]`\n\n`for record in records:`\n\n`channels = {record[\"channel\"] for record in records}`", "examples": [ex('campaigns = [{"name": "Search"}, {"name": "Social"}]\nfor campaign in campaigns:\n    print(campaign["name"])', 'Search\nSocial', "The list controls order; the dictionary controls field access."), ex('channels = {"paid", "organic", "paid"}\nprint(channels)', "{'paid', 'organic'}", "Sets retain one copy of each value; do not use them when order matters."), ex('remaining = 3\nwhile remaining:\n    print(remaining)\n    remaining -= 1', '3\n2\n1', "A while loop is appropriate when a counter is the state being changed.")], "domain": ex('campaigns = [{"name": "Search", "channel": "paid", "status": "active"}, {"name": "Social", "channel": "organic", "status": "paused"}]\nprint({c["channel"] for c in campaigns})', "{'paid', 'organic'}", "Unique channels are a set; campaign records remain ordered dictionaries in a list."), "mistakes": ["Using a set for records and losing order or duplicate evidence.", "Using an index when a `for record in records` loop is clearer.", "Accessing a missing dictionary key without deciding how to handle it."], "questions": ["Which structure stores many records?", "Why are channels a set?", "What should an empty campaign list return?"], "quiz": [("Which structure preserves duplicate records?", ["List", "Set", "None"], "a"), ("Which expression iterates fields?", ["`record.items()`", "`record.add()`", "`record.append()`"], "a")], "exercise": "Implement `summarize_campaigns(campaigns)` returning names in order, unique channels, and active records. Test normal and empty input plus one malformed record.", "solution": 'def summarize_campaigns(campaigns):\n    names, channels, active = [], set(), []\n    for campaign in campaigns:\n        name = campaign["name"]\n        channel = campaign["channel"]\n        names.append(name)\n        channels.add(channel)\n        if campaign.get("status") == "active":\n            active.append(campaign)\n    return {"names": names, "channels": channels, "active": active}', "test": "assert summarize_campaigns([]) == {\"names\": [], \"channels\": set(), \"active\": []}"},
    (3, 3): {"title": "State Changes and Termination", "intro": "A `while` loop is a promise to keep working while a condition is true. The promise is safe only when the loop changes state toward a reachable stopping point. This lesson makes the state transition visible before you use a loop in a retry, queue, or polling workflow.", "concepts": [("State", "Variables such as `attempt`, `index`, or `remaining` describe where the loop is now."), ("Transition", "The loop body changes state so the next condition check can differ."), ("Invariant", "A statement that should remain true during each iteration helps you reason about correctness."), ("Termination", "A bounded limit, empty queue, or successful condition must be reachable.")], "syntax": "`while state_is_valid(state):\n    state = next_state(state)`", "examples": [ex('remaining = 3\nwhile remaining > 0:\n    print(remaining)\n    remaining -= 1', '3\n2\n1', "The state moves 3 → 2 → 1 → 0."), ex('items = ["a", "b"]\nindex = 0\nwhile index < len(items):\n    print(items[index])\n    index += 1', 'a\nb', "The index changes after each access and reaches the list length."), ex('queue = ["metric-1"]\nwhile queue:\n    job = queue.pop(0)\n    print(job)', 'metric-1', "Removing work makes the queue condition eventually false.")], "domain": ex('attempt = 1\nmax_attempts = 3\nwhile attempt <= max_attempts:\n    print(f"collect metrics: {attempt}")\n    attempt += 1', 'collect metrics: 1\ncollect metrics: 2\ncollect metrics: 3', "A bounded collection retry has explicit state and a hard limit."), "mistakes": ["Changing a different variable than the one in the condition.", "Incrementing after a `continue` path is skipped.", "Using a condition that cannot become false."], "questions": ["Which variable changes?", "What value makes the condition false?", "What happens when the queue is empty before the loop starts?"], "quiz": [("What is a state transition?", ["A changed loop variable", "A print label", "A type annotation"], "a"), ("What proves termination?", ["A reachable stopping condition", "More output", "A larger list"], "a")], "exercise": "Implement `retry_states(max_attempts)` that returns each attempt and `drain_queue(items)` that removes each item exactly once. Add assertions for zero, one, and multiple items.", "solution": 'def retry_states(max_attempts):\n    states = []\n    attempt = 1\n    while attempt <= max_attempts:\n        states.append(attempt)\n        attempt += 1\n    return states\n\ndef drain_queue(items):\n    queue = list(items)\n    processed = []\n    while queue:\n        processed.append(queue.pop(0))\n    return processed', "test": "assert retry_states(3) == [1, 2, 3]; assert drain_queue([]) == []"},
    (3, 4): {"title": "Loop Boundary and Termination Tests", "intro": "A loop can look correct for ordinary input while failing at zero, one, the final allowed value, or an empty collection. Boundary tests make those cases executable. You are learning this now because retries, pages, records, and budgets all have limits in reliable automation.", "concepts": [("Boundary", "A value at, just below, or just above a limit."), ("Inclusive versus exclusive", "A condition such as `<=` includes the boundary; `range` stops before its stop value."), ("Termination assertion", "An assertion can check the state after a loop finishes."), ("Negative tests", "A test can prove that an invalid or empty input does not perform work.")], "syntax": "`assert actual == expected`\n\n`while current <= maximum:`\n\n`range(1, maximum + 1)`", "examples": [ex('for maximum in [0, 1, 3]:\n    values = list(range(1, maximum + 1))\n    print(maximum, values)', '0 []\n1 [1]\n3 [1, 2, 3]', "Zero is a meaningful boundary, not an error by itself."), ex('current = 1\nwhile current <= 3:\n    current += 1\nassert current == 4\nprint("terminated at", current)', 'terminated at 4', "The post-loop value proves why the condition became false."), ex('def count(items):\n    return sum(1 for _ in items)\nassert count([]) == 0', '','An empty iterable should not require a special fake item.')], "domain": ex('for limit in [0, 1, 3]:\n    attempts = list(range(1, limit + 1))\n    print({"limit": limit, "attempts": attempts, "within": len(attempts) <= limit})', "{'limit': 0, 'attempts': [], 'within': True}\n{'limit': 1, 'attempts': [1], 'within': True}\n{'limit': 3, 'attempts': [1, 2, 3], 'within': True}", "A test can prove a retry never exceeds its configured limit."), "mistakes": ["Testing only the happy-path value 3.", "Asserting the wrong post-loop value.", "Using a test that passes because it never enters the loop."], "questions": ["What should `range(1, 1)` contain?", "What is the final value after the inclusive loop?", "Which case catches an accidental extra attempt?"], "quiz": [("Which input exposes a skipped-first-item bug?", ["0 or 1", "100 only", "A string label"], "a"), ("What does a boundary test compare?", ["Observed and expected edge behavior", "Only formatting", "A username"], "a")], "exercise": "Write `test_loop_boundaries()` for maximum values 0, 1, and 3. Verify produced attempts, post-loop state, and that an empty input performs zero iterations.", "solution": 'def loop_values(maximum):\n    values = []\n    current = 1\n    while current <= maximum:\n        values.append(current)\n        current += 1\n    assert current == maximum + 1\n    return values\n\ndef test_loop_boundaries():\n    assert loop_values(0) == []\n    assert loop_values(1) == [1]\n    assert loop_values(3) == [1, 2, 3]', "test": "test_loop_boundaries()"},
    (3, 5): {"title": "Semantic Git Diff Review", "intro": "A clean diff tells a reviewer what changed and why. This lesson applies the loop-boundary mindset to Git: inspect the meaningful lines, separate noise, and verify that tests changed with the behavior. It prepares you to package course projects without hiding accidental edits.", "concepts": [("Semantic change", "A line that changes program behavior, tests, or documentation intentionally."), ("Noise", "Generated files, line-ending changes, and OS metadata that obscure meaning."), ("Focused diff", "A diff limited to the current lesson's files."), ("Review evidence", "A short note connecting the diff to the acceptance criteria.")], "syntax": "`git diff --stat`\n\n`git diff --check`\n\n`git diff --cached -- path`", "examples": [ex('diff = ["+attempt += 1", "+print(secret)"]\nprint([line for line in diff if "secret" not in line])', '[\'+attempt += 1\']', "Review can identify unsafe output before a commit."), ex('files = ["exercise.py", "test_exercise.py", ".DS_Store"]\nprint([f for f in files if f.endswith(".py")])', '[\'exercise.py\', \'test_exercise.py\']', "The expected artifact set is explicit." )], "domain": ex('changed = ["campaign_rules.py", "campaign_rules_test.py", "report.json"]\nprint({"semantic": changed[:2], "noise_or_output": changed[2:]})', "{'semantic': ['campaign_rules.py', 'campaign_rules_test.py'], 'noise_or_output': ['report.json']}", "Generated reports can be preserved locally without becoming source."), "mistakes": ["Calling all changed lines noise without reading them.", "Committing a report instead of the code and test that produced it.", "Ignoring whitespace errors detected by `git diff --check`."], "questions": ["Which files belong to the lesson?", "What makes a change semantic?", "Why review staged and unstaged diffs separately?"], "quiz": [("What does `git diff --check` find?", ["Whitespace errors", "Python types", "API results"], "a"), ("Which artifact is usually generated?", ["A source module", "A report JSON", "A test assertion"], "b")], "exercise": "Create a review report from a supplied list of changed files. Classify semantic source/test files versus generated/noise files and write the exact Git commands a learner should run before committing.", "solution": 'def review_paths(paths):\n    semantic, excluded = [], []\n    for path in paths:\n        if path == ".DS_Store" or path.endswith(".pyc") or path.endswith(".json"):\n            excluded.append(path)\n        else:\n            semantic.append(path)\n    return {"semantic": semantic, "excluded": excluded}', "test": "assert review_paths([\"exercise.py\", \"report.json\", \".DS_Store\"])[\"excluded\"] == [\"report.json\", \".DS_Store\"]"},
    (3, 6): {"title": "Blank-File Campaign Rules Checker", "intro": "This is the Week 3 mastery project. You will start from a blank implementation and use lists, dictionaries, sets, conditionals, loops, functions, and tests to identify fictional campaigns that violate spend or CPA rules. The project proves retrieval, not copying.", "concepts": [("Record validation", "Reject missing or malformed numeric fields before arithmetic."), ("Rule evaluation", "Apply deterministic thresholds one campaign at a time."), ("Evidence", "Return campaign ID, violated rule, and observed value."), ("Blank-file retrieval", "The requirements and tests are available; the implementation is yours.")], "syntax": "`def check_campaigns(campaigns, max_spend, max_cpa):`\n\n`return {\"violations\": [...], \"rejected\": [...]}`", "examples": [ex('campaign = {"id": "search", "spend": 500, "conversions": 20}\ncpa = campaign["spend"] / campaign["conversions"]\nprint(cpa)', '25.0', "Arithmetic is deterministic and should handle zero conversions explicitly."), ex('campaign = {"id": "social", "spend": 300, "conversions": 0}\nprint({"id": campaign["id"], "reason": "zero conversions"})', "{'id': 'social', 'reason': 'zero conversions'}", "A zero denominator is evidence to classify, not a crash to ignore.")], "domain": ex('campaigns = [{"id": "search", "spend": 500, "conversions": 20}]\nprint([c["id"] for c in campaigns if c["spend"] > 400])', '[\'search\']', "The final project is local fictional data; no advertising platform is contacted."), "mistakes": ["Dividing by zero when conversions are zero.", "Dropping malformed records instead of preserving rejection evidence.", "Letting a model decide arithmetic or thresholds."], "questions": ["Which fields are required?", "What should zero conversions mean?", "How will a violation be explained?"], "quiz": [("Who calculates CPA?", ["Deterministic Python", "A prose prompt", "A random guess"], "a"), ("What belongs in rejected evidence?", ["Input and reason", "Only the ID", "Nothing"], "a")], "exercise": "From an empty file, implement `check_campaigns(campaigns, max_spend, max_cpa)`. Return violations and rejected records, handle zero conversions and malformed data, and add normal/boundary/invalid tests.", "solution": 'def check_campaigns(campaigns, max_spend, max_cpa):\n    violations, rejected = [], []\n    for campaign in campaigns:\n        try:\n            spend = campaign["spend"]\n            conversions = campaign["conversions"]\n            if conversions == 0:\n                rejected.append({"id": campaign.get("id"), "reason": "zero conversions"})\n                continue\n            cpa = spend / conversions\n        except (KeyError, TypeError):\n            rejected.append({"id": campaign.get("id"), "reason": "malformed record"})\n            continue\n        if spend > max_spend or cpa > max_cpa:\n            violations.append({"id": campaign.get("id"), "spend": spend, "cpa": cpa})\n    return {"violations": violations, "rejected": rejected}', "test": "assert check_campaigns([], 100, 10) == {\"violations\": [], \"rejected\": []}"},
    (3, 7): {"title": "Optional Review and Recovery: Loops and Collections", "intro": "Review days are optional retrieval practice. You pause new material, rebuild the week's smallest examples without notes, and record which concept needs another attempt. This prevents a passing guided exercise from being mistaken for independent mastery.", "concepts": [("Retrieval", "Rebuild from requirements rather than copying a previous file."), ("Reflection", "Name the exact concept or boundary that remains uncertain."), ("Recovery plan", "Choose one small next attempt with a testable result."), ("No new scope", "Review improves reliability without adding a new framework.")], "syntax": "`assert explanation`\n\n`python -m unittest -v`", "examples": [ex('values = list(range(1, 4))\nassert values == [1, 2, 3]\nprint("retrieved")', 'retrieved', "A small assertion can prove a recalled boundary."), ex('records = [{"channel": "paid"}, {"channel": "paid"}]\nassert {r["channel"] for r in records} == {"paid"}', '','The set assertion checks uniqueness without discarding the original list.')], "domain": ex('goal = {"concept": "campaign rules", "next_attempt": "test zero conversions"}\nprint(goal)', "{'concept': 'campaign rules', 'next_attempt': 'test zero conversions'}", "A review note points to a concrete MarketingOps capability without pretending it is mastered."), "mistakes": ["Reading the solution before attempting retrieval.", "Writing a vague reflection such as `loops are hard`.", "Adding new project scope instead of fixing one weak boundary."], "questions": ["Which concept can you rebuild without notes?", "Which boundary failed?", "What is the smallest next test?"], "quiz": [("What is the goal of review day?", ["Honest retrieval", "More frameworks", "Skipping tests"], "a"), ("What makes a recovery plan useful?", ["A concrete next attempt", "A vague feeling", "No evidence"], "a")], "exercise": "Create a short retrieval report with one rebuilt loop, one collection transformation, one failing or boundary test, and a next-attempt note. Day 7 is optional and does not count toward required completion.", "solution": 'def retrieval_report():\n    attempts = list(range(1, 4))\n    channels = {"paid", "organic"}\n    return {"loops_rebuilt": attempts, "unique_channels": sorted(channels), "next_attempt": "test zero conversions"}\n\nprint(retrieval_report())', "test": "assert retrieval_report()[\"loops_rebuilt\"] == [1, 2, 3]"},
})


def navigation(week: int, day: int, unit: dict[str, str]) -> str:
    current = lesson_directory(week, day, unit)
    if day > 1:
        previous = lesson_directory(week, day - 1, unit_for_day(week, day - 1))
    elif week > 1:
        previous = lesson_directory(week - 1, 7, unit_for_day(week - 1, 7))
    else:
        previous = None
    if day < 7:
        following = lesson_directory(week, day + 1, unit_for_day(week, day + 1))
    elif week < 36:
        following = lesson_directory(week + 1, 1, unit_for_day(week + 1, 1))
    else:
        following = None
    links = []
    if previous:
        links.append(f"[← Previous lesson]({Path('..', '..', previous.relative_to(ROOT / 'course-lessons')).as_posix()}/instructions.md)")
    links.append("[Week overview](../README.md)")
    links.append("[Full curriculum](../../README.md)")
    if following:
        links.append(f"[Next lesson →]({Path('..', '..', following.relative_to(ROOT / 'course-lessons')).as_posix()}/instructions.md)")
    return " · ".join(links)


def render(week: int, day: int, data: dict[str, object]) -> str:
    unit = unit_for_day(week, day)
    sections = data["concepts"]
    examples = data["examples"]
    quiz = data["quiz"]
    status = "Authored" if week <= 2 else "Authored (partial)"
    lines = [f"# Week {week:02d}, Day {day:02d}: {data['title']}", "", f"**Content status:** {status}", f"**Required:** {'Yes' if day <= 6 else 'Optional review'}", f"**Estimated time:** 90 minutes", "", "## Why this lesson matters", "", str(data["intro"]), "", "## What you will learn", "", "By the end of this lesson, you will be able to:", "", *[f"- {body.split('.')[0]}." for _heading, body in sections], "", "## Concepts", ""]
    for heading, body in sections:
        lines.extend([f"### {heading}", "", body, ""])
    lines.extend(["## Syntax", "", str(data["syntax"]), "", "## Worked examples", ""])
    lines.extend(examples)
    lines.extend(["", "## MarketingOps example", "", str(data["domain"]), "", "This fictional example reinforces the Python concept. It does not call a live API, use credentials, or authorize an external action.", "", "## Common mistakes and failure cases", ""])
    lines.extend(f"- {item}" for item in data["mistakes"])
    lines.extend(["", "## Check your understanding", ""])
    lines.extend(f"{index}. {question}" for index, question in enumerate(data["questions"], 1))
    lines.extend(["", "<details>", "<summary>Think through the questions</summary>", "", "Try the examples and write predictions before opening the reference file.", "", "</details>", "", "## Quiz", ""])
    for index, (question, options, answer) in enumerate(quiz, 1):
        lines.append(f"{index}. **{question}**")
        lines.extend(f"   - {letter}) {option}" for letter, option in zip("abc", options))
    lines.extend(["", "<details>", "<summary>Answer key and explanations</summary>", "", *[f"{index}. **{answer}** — The correct choice follows the rule taught above." for index, (_q, _o, answer) in enumerate(quiz, 1)], "", "</details>", "", "## Exercise handoff", "", str(data["exercise"]), "", "Open [`exercise.py`](exercise.py) and write the implementation yourself. Run:", "", "```bash", "python exercise.py", "python -m unittest -v", "```", "", "The exercise must cover normal input, at least one boundary, and the failure or malformed case named above. Use the hints in the exercise file only after your first attempt. Inspect [`solution.py`](solution.py) only after your tests run or you can explain the remaining failure.", "", "## Weekly project connection", "", f"This contributes to the Week {week:02d} project by making `{unit['capabilities'][-1]}` more testable and reviewable.", "", "## Official reading", "", "[Python documentation](https://docs.python.org/3/tutorial/) — use the relevant section for this lesson's syntax and behavior.", "", "## Navigation", "", navigation(week, day, unit), ""])
    return "\n".join(lines)


def main() -> None:
    for key, data in LESSONS.items():
        week, day = key
        unit = unit_for_day(week, day)
        directory = lesson_directory(week, day, unit)
        directory.mkdir(parents=True, exist_ok=True)
        (directory / "instructions.md").write_text(render(week, day, data), encoding="utf-8")
        solution_text = str(data["solution"])
        function_matches = re.findall(r"^def (\w+)\(([^)]*)\):", solution_text, re.MULTILINE)
        starter = [f'''"""Student exercise for Week {week:02d}, Day {day:02d}.\n\nRead instructions.md first. Write the implementation; do not copy solution.py.\n"""''', "", "# Requirements", f"# {data['exercise']}", "", "# Add normal, boundary, and failure assertions for the cases in the lesson."]
        if function_matches:
            for name, signature in function_matches:
                starter.extend(["", f"def {name}({signature}):", "    \"\"\"TODO: implement the lesson contract.\"\"\"", "    raise NotImplementedError"])
        else:
            starter.extend(["", "# Write the requested program here.", "raise NotImplementedError"])
        (directory / "exercise.py").write_text("\n".join(starter) + "\n", encoding="utf-8")
        test_body = str(data["test"])
        imports = "from exercise import *\n"
        if "Path(" in test_body:
            imports = "from pathlib import Path\nfrom exercise import *\n"
        test_text = f'''"""Acceptance checks for this lesson. They intentionally fail until exercise.py is written."""\n\n{imports}\n\ndef test_acceptance():\n    {test_body}\n'''
        (directory / "test_exercise.py").write_text(test_text, encoding="utf-8")
        (directory / "solution.py").write_text(solution_text + "\n", encoding="utf-8")
    print(f"Authored {len(LESSONS)} foundation lesson instruction files")


if __name__ == "__main__":
    main()
